function renderNav(){Object.entries(navGroups).forEach(([group,items])=>{$(`#${group}-nav`).innerHTML=items.map(([id,icon,label])=>`<button class="nav-item ${id===active?'active':''}" data-page="${id}"><span class="nav-icon">${icon}</span><span>${label}</span></button>`).join('')});document.querySelectorAll('.nav-item').forEach(item=>item.addEventListener('click',()=>{active=item.dataset.page;renderNav();renderPage();if(window.innerWidth<901)$('#sidebar').classList.remove('open')}))}
