function overview(){const metrics=[['pending','Open inspections','24','+12% this month','◷'],['report','Pass rate','96.4%','+2.1% this month','✓'],['gauges','Instruments due','08','Next 30 days','⌁'],['nc-stock','Open NC stock','17','3 need action','△']];return `<div class="hero-grid"><section class="welcome-panel panel"><span class="signal-tag">SYSTEM STATUS · OPTIMAL</span><h2>Good afternoon, Quality Manager</h2><p>Keep every inspection, instrument, and process in view. Your quality workspace is ready for today's checks.</p><button class="primary" data-page="report">Create inspection report <span>→</span></button></section><div class="metric-grid">${metrics.map(x=>`<button class="metric" data-page="${x[0]}" title="Open ${x[1]}"><div class="metric-top"><span>${x[1]}</span><span>${x[4]}</span></div><strong>${x[2]}</strong><small>${x[3]} <b>↗</b></small></button>`).join('')}</div></div><section class="panel"><div class="section-head"><div><span class="section-kicker">QUALITY TELEMETRY</span><h2>Inspection performance</h2><p id="chart-caption">Quality results across the last six months</p></div><label class="period-control"><span>Period</span><select class="period-select" data-period="6"><option value="3">Last 3 months</option><option value="6" selected>Last 6 months</option><option value="12">Last 12 months</option></select></label></div><div class="chart-wrap"><div class="chart" id="performance-chart">${[45,64,52,78,67,91].map(n=>`<div class="bar-group"><div class="bar" style="height:${n*.7}%"></div><div class="bar accent" style="height:${n}%"></div></div>`).join('')}</div><div class="chart-labels"><span>Mar</span><span>Apr</span><span>May</span><span>Jun</span><span>Jul</span><span>Aug</span></div></div></section><div style="height:22px"></div><div class="quick-grid"><div class="quick panel" data-page="instruments"><div class="quick-icon">⌁</div><h3>Instrument register</h3><p>8 calibrations due soon</p></div><div class="quick panel" data-page="products"><div class="quick-icon">◇</div><h3>Product quality</h3><p>42 active checklists</p></div><div class="quick panel" data-page="report"><div class="quick-icon">▥</div><h3>Reports</h3><p>Generate inspection insights</p></div></div>`}
