function ncStockPage(){const rows=[['NC-204','Bearing housing','Mechanical','pending'],['NC-201','Valve seal set','Hydraulic','approved'],['NC-198','Gear shaft','Transmission','pending']];return shell(`<div class="workspace-heading"><div><span class="workspace-kicker">NC INVENTORY</span><h2>NC Stock</h2><p>Track rejected and non-conforming material held for disposition.</p></div><button class="primary" data-nc-action="create">＋ Add NC stock</button></div><div class="workspace-summary"><div><strong>${rows.length}</strong><span>NC items</span></div><div><strong>${rows.filter(row=>row[3]==='pending').length}</strong><span>Awaiting review</span></div><div><strong>${rows.filter(row=>row[3]==='approved').length}</strong><span>Approved</span></div></div><div class="workspace-toolbar"><input class="search" placeholder="⌕  Search NC item or category..." data-nc-search><select class="select" data-nc-status><option value="all">All status</option><option value="pending">Pending</option><option value="approved">Approved</option></select></div><div class="table-wrap"><table class="table"><thead><tr><th>NC ID</th><th>Item</th><th>Category</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(row=>`<tr data-nc-row data-id="${row[0]}" data-status="${row[3]}"><td>${row[0]}</td><td>${row[1]}</td><td>${row[2]}</td><td><span class="pill ${row[3]}">${row[3]}</span></td><td><button class="small-btn" data-nc-action="status">Status</button> <button class="small-btn edit" data-nc-action="view">View</button></td></tr>`).join('')}</tbody></table></div><div class="workspace-footer"><span data-nc-count>Showing ${rows.length} of ${rows.length} NC items</span><button class="text-button" data-nc="activity">View activity log →</button></div><div class="nc-drawer" data-nc-drawer hidden></div>`) }
