function bindOutsourceActions(){
  const rows=[...document.querySelectorAll('[data-outsource-row]')];
  const filter=()=>{
    const query=($('[data-outsource-search]')?.value||'').toLowerCase();
    const status=$('[data-outsource-status]')?.value||'all';
    rows.forEach(row=>{
      const matchesQuery=!query||row.textContent.toLowerCase().includes(query);
      const matchesStatus=status==='all'||row.dataset.status===status;
      row.hidden=!(matchesQuery&&matchesStatus);
    });
    const count=$('[data-outsource-count]');
    if(count)count.textContent=`Showing ${[...document.querySelectorAll('[data-outsource-row]')].filter(row=>!row.hidden).length} of ${rows.length} transfers`;
  };

  $('[data-outsource-search]')?.addEventListener('input',filter);
  $('[data-outsource-status]')?.addEventListener('change',filter);

  document.querySelectorAll('[data-outsource-action]').forEach(action=>{
    action.addEventListener('click',event=>{
      event.preventDefault();
      const row=action.closest('[data-outsource-row]');
      if(!row && action.dataset.outsourceAction!=='create') return;

      if(action.dataset.outsourceAction==='create'){
        const drawer=$('[data-outsource-drawer]');
        if(drawer){
          drawer.hidden=false;
          drawer.innerHTML='<strong>New transfer created</strong><p>Transfer OUT-105 sent to Precision Works for heat treatment lot.</p>';
        }
        showToast('Transfer created successfully');
        return;
      }

      if(action.dataset.outsourceAction==='view'){
        const drawer=$('[data-outsource-drawer]');
        if(drawer){
          drawer.hidden=false;
          drawer.innerHTML=`<strong>${row.dataset.transfer} summary</strong><p>Vendor: ${row.children[1].textContent} � Material: ${row.children[2].textContent} � Expected: ${row.children[3].textContent} � Status: ${row.dataset.status}</p>`;
        }
        return;
      }

      if(action.dataset.outsourceAction==='status'){
        const next=row.dataset.status==='pending'?'approved':'pending';
        row.dataset.status=next;
        const pill=row.querySelector('.pill');
        if(pill){
          pill.className=`pill ${next}`;
          pill.textContent=next;
        }
        showToast(`Transfer ${row.dataset.transfer} marked as ${next}`);
        filter();
      }
    });
  });

  const activityButton=$('[data-outsource="activity"]');
  if(activityButton){
    activityButton.addEventListener('click',()=>{
      const drawer=$('[data-outsource-drawer]');
      if(drawer){
        drawer.hidden=false;
        drawer.innerHTML='<strong>Activity log</strong><p>OUT-104 sent to Precision Works · Today, 09:12</p><p>OUT-103 completed by Finishing Hub · Yesterday, 16:40</p><p>OUT-102 flagged for vendor follow-up · Today, 07:30</p>';
      }
    });
  }
}
function bindInstrumentListActions(){document.querySelectorAll('[data-instrument-action]').forEach(action=>action.addEventListener('click',event=>{event.preventDefault();const type=action.dataset.instrumentAction;if(type==='view'){const row=action.closest('[data-instrument-row]');const detail=$('[data-instrument-detail]');detail.hidden=false;detail.innerHTML=`<strong>${row.children[1].textContent} · ${action.dataset.instrumentId}</strong><p>Category: ${row.children[2].textContent} · Location: ${row.children[3].textContent} · Calibration due: ${row.children[4].textContent}</p>`;detail.scrollIntoView({behavior:'smooth',block:'nearest'});return}if(type==='delete'){const row=action.closest('[data-instrument-row]');const id=action.dataset.instrumentId;const records=JSON.parse(localStorage.getItem('qms-instruments')||'[]').filter(item=>item.id!==id);localStorage.setItem('qms-instruments',JSON.stringify(records));row.remove();updateInstrumentCount();showToast('Instrument deleted from register');return}if(type==='export'){const rows=[...document.querySelectorAll('[data-instrument-row]:not([hidden])')].map(row=>[...row.children].slice(0,6).map(cell=>cell.textContent.trim()));const csv=[['Instrument ID','Instrument','Category / sub-category','Location','Calibration due','Status'],...rows].map(row=>row.map(cell=>`"${cell.replaceAll('"','""')}"`).join(',')).join('\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));link.download='instrument-register.csv';link.click();URL.revokeObjectURL(link.href);showToast('Instrument register exported');}}))}
function bindOperationForms(){document.querySelectorAll('[data-operation-form]').forEach(form=>form.addEventListener('submit',event=>{event.preventDefault();const data=Object.fromEntries(new FormData(form));if(form.dataset.operationForm==='instruments'){const records=JSON.parse(localStorage.getItem('qms-instruments')||'[]');records.push(data);localStorage.setItem('qms-instruments',JSON.stringify(records));form.reset();const success=form.parentElement.querySelector('[data-instrument-success]');success.hidden=false;success.textContent=`${data.name} (${data.id}) was added to the instrument register.`;showToast('Instrument added successfully');return}if(form.dataset.operationForm==='instrument-categories'){const records=JSON.parse(localStorage.getItem('qms-instrument-categories')||'[]');records.push(data);localStorage.setItem('qms-instrument-categories',JSON.stringify(records));form.reset();const success=form.parentElement.querySelector('[data-category-success]');success.hidden=false;success.textContent=`${data.category} / ${data.subcategory} was added successfully.`;showToast('Instrument category added successfully');return}showToast(`${pageMeta[form.dataset.operationForm][0]} saved successfully`)}))}
