function bindSubAssemblyActions(){const filter=()=>{const query=($('[data-assembly-search]')?.value||'').toLowerCase();const status=$('[data-assembly-status]')?.value||'all';document.querySelectorAll('[data-assembly-card]').forEach(card=>card.hidden=(query&&!card.textContent.toLowerCase().includes(query))||(status!=='all'&&card.dataset.status!==status))};$('[data-assembly-search]')?.addEventListener('input',filter);$('[data-assembly-status]')?.addEventListener('change',filter);document.querySelectorAll('[data-assembly-action]').forEach(action=>action.addEventListener('click',()=>{const card=action.closest('[data-assembly-card]');const id=card.dataset.assemblyId;if(action.dataset.assemblyAction==='delete'){card.remove();showToast('Sub assembly deleted');return}const editor=$('[data-assembly-editor]');editor.hidden=false;editor.innerHTML=`<form class="inline-editor" data-assembly-edit-form><strong>Edit ${id}</strong><input class="field" name="name" value="${card.querySelector('h3').textContent}" required><select class="field" name="status"><option ${card.dataset.status==='approved'?'selected':''}>approved</option><option ${card.dataset.status==='pending'?'selected':''}>pending</option><option ${card.dataset.status==='rejected'?'selected':''}>rejected</option></select><button class="primary" type="submit">Save changes</button></form>`;editor.querySelector('form').addEventListener('submit',event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget));card.querySelector('h3').textContent=data.name;card.dataset.status=data.status;card.querySelector('.pill').className=`pill ${data.status}`;card.querySelector('.pill').textContent=data.status;editor.hidden=true;showToast('Sub assembly updated');filter()})}))}
function bindDirectProductActions(){const filter=()=>{const query=($('[data-direct-search]')?.value||'').toLowerCase();const status=$('[data-direct-status]')?.value||'all';document.querySelectorAll('[data-direct-product]').forEach(card=>{card.hidden=(query&&!card.textContent.toLowerCase().includes(query))||(status!=='all'&&card.dataset.status!==status)})};$('[data-direct-search]')?.addEventListener('input',filter);$('[data-direct-status]')?.addEventListener('change',filter);document.querySelectorAll('[data-direct-action]').forEach(action=>action.addEventListener('click',()=>{const card=action.closest('[data-direct-product]');const id=card.dataset.productId;if(action.dataset.directAction==='delete'){const deleted=JSON.parse(localStorage.getItem('qms-deleted-products')||'[]');if(!deleted.includes(id))deleted.push(id);localStorage.setItem('qms-deleted-products',JSON.stringify(deleted));card.remove();showToast('Direct product deleted');return}const editor=$('[data-product-editor]');editor.hidden=false;editor.innerHTML=`<form class="inline-editor" data-product-edit-form><strong>Edit ${id}</strong><input class="field" name="name" value="${card.querySelector('h3').textContent}"><select class="field" name="status"><option ${card.dataset.status==='approved'?'selected':''}>approved</option><option ${card.dataset.status==='pending'?'selected':''}>pending</option><option ${card.dataset.status==='rejected'?'selected':''}>rejected</option></select><button class="primary" type="submit">Save changes</button></form>`;editor.querySelector('form').addEventListener('submit',event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget));card.querySelector('h3').textContent=data.name;card.dataset.status=data.status;card.querySelector('.pill').className=`pill ${data.status}`;card.querySelector('.pill').textContent=data.status;editor.hidden=true;showToast('Direct product updated')})}));}
