document.addEventListener('input',event=>{if(!event.target.matches('[data-instrument-search]'))return;const query=event.target.value.toLowerCase();document.querySelectorAll('[data-instrument-row]').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(query));updateInstrumentCount()});document.addEventListener('change',event=>{if(!event.target.matches('[data-instrument-status]'))return;const status=event.target.value;document.querySelectorAll('[data-instrument-row]').forEach(row=>row.hidden=status!=='all'&&row.dataset.status!==status);updateInstrumentCount()});document.addEventListener('click',event=>{const action=event.target.closest('[data-instrument-action]');if(!action)return;const type=action.dataset.instrumentAction;if(type==='view'){const row=action.closest('[data-instrument-row]');const detail=$('[data-instrument-detail]');detail.hidden=false;detail.textContent=`Instrument ${action.dataset.instrumentId}: ${row.children[1].textContent} is registered at ${row.children[3].textContent}. Calibration due ${row.children[4].textContent}.`}if(type==='delete'){const row=action.closest('[data-instrument-row]');const id=action.dataset.instrumentId;const records=JSON.parse(localStorage.getItem('qms-instruments')||'[]').filter(item=>item.id!==id);localStorage.setItem('qms-instruments',JSON.stringify(records));row.remove();updateInstrumentCount();showToast('Instrument removed from register')}if(type==='export')showToast('Instrument register export ready')});
function generateInspectionReport(form){const start=form.elements.startDate.value||'Not set';const end=form.elements.endDate.value||'Not set';const type=form.elements.inspectionType.value||'Sub Assembly';const result=form.elements.result.value||'All results';const remarks=(form.elements.remarks.value||'').trim()||'No additional remarks';const rows=[['Period','Value'],['Start date',start],['End date',end],['Inspection type',type],['Result filter',result],['Remarks',remarks]];const csv=[['Field','Value'],...rows].map(row=>row.map(cell=>`"${String(cell).replaceAll('"','""')}"`).join(',')).join('\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));link.download=`inspection-report-${Date.now()}.csv`;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(link.href);const existing=form.parentElement.querySelector('.report-summary');if(existing)existing.remove();const summary=document.createElement('div');summary.className='report-summary panel';summary.innerHTML=`<div class="section-head" style="padding:0 0 14px"><div><span class="workspace-kicker">REPORT GENERATED</span><h3>Inspection summary</h3></div></div><div class="stats-row"><div class="mini-stat"><span>Period</span><strong>${start} to ${end}</strong></div><div class="mini-stat"><span>Inspection type</span><strong>${type}</strong></div><div class="mini-stat"><span>Result filter</span><strong>${result}</strong></div></div><p><strong>Remarks:</strong> ${remarks}</p>`;form.insertAdjacentElement('afterend',summary);return rows;}
function renderPage(){const meta=pageMeta[active];$('#page-title').textContent=meta[0];$('#welcome').textContent=`Welcome, ${meta[1]}`;const requested=active==='pending'?pendingPage():active==='instruments'?instrumentEntryPage():active==='instrument-list'?instrumentListPage():active==='instrument-categories'?instrumentCategoryPage():active==='direct-finish'?directFinishPage():active==='outsource'?outsourcePage():active==='drawings'?drawingsPage():active==='npd'?npdPage():active==='returns'?returnsPage():active==='nc-stock'?ncStockPage():active==='rejection'?rejectionPage():active==='rw-stock'?rwStockPage():active==='grn'?grnPage():active==='last-process'?lastProcessPage():requestedOperation(active);let html=requested|| (active==='overview'?overview():active==='products'?directProductsPage():active==='assemblies'?subAssemblyPage():active==='report'?report():active==='gauges'?instrumentForm():active==='invoices'?invoices():workspacePage(active));$('#content').innerHTML=html;bindContent();bindOperationForms();if(active==='instrument-list')bindInstrumentListActions();if(active==='products')bindDirectProductActions();if(active==='direct-finish')bindDirectFinishActions();if(active==='assemblies')bindSubAssemblyActions();if(active==='outsource')bindOutsourceActions();if(active==='drawings')bindDrawingsActions();if(active==='npd')bindNpdActions();if(active==='returns')bindReturnsActions();if(active==='nc-stock')bindNcActions();if(active==='rejection')bindRejectionActions();if(active==='rw-stock')bindRwActions();if(active==='grn')bindGrnActions();if(active==='last-process')bindLastProcessActions()}
