document.addEventListener('input',event=>{if(!event.target.matches('[data-pending-search]'))return;const query=event.target.value.toLowerCase();document.querySelectorAll('[data-pending-row]').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(query));updatePendingCount()});document.addEventListener('change',event=>{if(!event.target.matches('[data-pending-status]'))return;filterPending(event.target.value)});document.addEventListener('click',event=>{const target=event.target.closest('[data-pending]');if(!target)return;if(target.dataset.pending==='filter'){$('[data-pending-panel]').hidden=!$('[data-pending-panel]').hidden}if(target.dataset.pending==='activity'){$('[data-pending-drawer]').hidden=false;$('[data-pending-drawer]').innerHTML='<strong>Activity log</strong><p>PO-2024-021 submitted by Stores · Today, 09:42</p><p>PO-2024-019 approved by Quality · Today, 08:15</p>'}if(target.dataset.pending==='review'){$('[data-pending-drawer]').hidden=false;$('[data-pending-drawer]').innerHTML=`<strong>Review ${target.dataset.po}</strong><p>Check supplier documents, quantity, and incoming quality records.</p><button class="primary" data-action="toast">Mark reviewed</button>`}const statusButton=event.target.closest('[data-pending-status-button]');if(statusButton){filterPending(statusButton.dataset.pendingStatusButton)}});function filterPending(status){document.querySelectorAll('[data-pending-row]').forEach(row=>row.hidden=status!=='all'&&row.dataset.status!==status);updatePendingCount()}function updatePendingCount(){const visible=[...document.querySelectorAll('[data-pending-row]')].filter(row=>!row.hidden).length;const count=$('[data-pending-count]');if(count)count.textContent=`Showing ${visible} of 3 purchase orders`}
